/**
 * RmlUi modifier flags; combine flags with bitwise OR.
 *
 * @zh RmlUi 修饰键标志；使用按位或组合。
 * @ja RmlUi 修飾キーフラグ。ビット OR で組み合わせます。
 * @ko RmlUi 보조 키 플래그입니다. 비트 OR로 결합합니다.
 */
export enum KeyModifier {
  /**
   * Set when Control is held down.
   *
   * @zh Control 按下时设置的标志。
   * @ja Control が押されているときのフラグ。
   * @ko Control 누름 상태 플래그입니다.
   */
  KM_CTRL = 1,
  /**
   * Set when Shift is held down.
   *
   * @zh Shift 按下时设置的标志。
   * @ja Shift が押されているときのフラグ。
   * @ko Shift 누름 상태 플래그입니다.
   */
  KM_SHIFT = 2,
  /**
   * Set when Alt is held down.
   *
   * @zh Alt 按下时设置的标志。
   * @ja Alt が押されているときのフラグ。
   * @ko Alt 누름 상태 플래그입니다.
   */
  KM_ALT = 4,
  /**
   * Set when Meta / Command is held down.
   *
   * @zh Meta / Command 按下时设置的标志。
   * @ja Meta / Command が押されているときのフラグ。
   * @ko Meta / Command 누름 상태 플래그입니다.
   */
  KM_META = 8,
  /**
   * Set when Caps Lock is enabled.
   *
   * @zh Caps Lock 启用时设置的标志。
   * @ja Caps Lock が有効ときのフラグ。
   * @ko Caps Lock 활성화 상태 플래그입니다.
   */
  KM_CAPSLOCK = 16,
  /**
   * Set when Num Lock is enabled.
   *
   * @zh Num Lock 启用时设置的标志。
   * @ja Num Lock が有効ときのフラグ。
   * @ko Num Lock 활성화 상태 플래그입니다.
   */
  KM_NUMLOCK = 32,
  /**
   * Set when Scroll Lock is enabled.
   *
   * @zh Scroll Lock 启用时设置的标志。
   * @ja Scroll Lock が有効ときのフラグ。
   * @ko Scroll Lock 활성화 상태 플래그입니다.
   */
  KM_SCROLLLOCK = 64,
}
